Theorem phase2 : forall G (fx : FPState) E R M,
  chainT2 G -> AT2 G E R M -> Θ 27%nat = Z_to_bv 64 (fr_sp (lastf G CATCHd)) ->
  exists (fx' : FPState) E' R' M' t,
       first_pad G = Some t
    /\ msteps EhX_plain.SEGS (@mkst fx R (Z_to_bv 64 CUT1_PC) M (seg_rom EhX_plain.SEGS))
                             (@mkst fx' R' (Z_to_bv 64 (pad_pc t)) M' (seg_rom EhX_plain.SEGS))
    /\ @fp_csr fx' = @fp_csr fx
    /\ regs_ok E' (PAD_regs (pad_sel t)) R' /\ know_ok EhX_plain.SEGS E' M' PAD_T /\ envT2 E'
    /\ ev E' 34%nat = Z_to_bv 64 (fr_sp (fst t))
    /\ (forall k, (k < 12)%nat -> ev E' (slot_var k) = live (fst t) k)
    /\ (forall a, A + TOP <= a < 2^64 -> M' (Z_to_bv 64 a) = M0 (Z_to_bv 64 a))
    /\ (forall a : word, ~ zone2 (bv_unsigned a) -> ~ (H <= bv_unsigned a < H + 144) -> M' a = M a)
